<script setup>import {ref,computed} from 'vue';import MdmShell from '../../components/MdmShell.vue';import StatusPill from '../../components/StatusPill.vue';import {demands} from '../../api/mock';const active=ref('全部');const tabs=['全部','待转采购','已转采购','平衡完成'];const list=computed(()=>active.value==='全部'?demands:demands.filter(x=>x.status===active.value));</script>
<template><MdmShell><template #title>数据标准</template><div class="page-actions"><div class="tabs"><button v-for="t in tabs" :key="t" :class="{active:t===active}" @click="active=t">{{t}} <small>{{t==='全部'?demands.length:demands.filter(x=>x.status===t).length}}</small></button></div><div><button class="ghost">导入预测</button><button class="primary">＋ 新建数据标准</button></div></div><section class="panel table-panel"><div class="tools"><div class="search">⌕ <input placeholder="搜索计划单、物料编码或名称"/></div><button>需求日期：未来 30 天⌄</button><button>来源：全部⌄</button><button>风险等级：全部⌄</button></div><table><thead><tr><th><input type="checkbox"/></th><th>计划单号</th><th>物料</th><th>需求来源</th><th>需求数量</th><th>可用库存</th><th>供需缺口</th><th>需求日期</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="d in list" :key="d.no"><td><input type="checkbox"/></td><td><b>{{d.no}}</b><small>风险 {{d.risk}}</small></td><td><b>{{d.material}}</b><small>{{d.code}}</small></td><td>{{d.source}}</td><td><b>{{d.qty}}</b></td><td>{{d.stock}}</td><td><strong :class="d.gap.startsWith('-')?'danger':'success'">{{d.gap}}</strong></td><td>{{d.date}}</td><td><StatusPill :status="d.status"/></td><td><button class="more">•••</button></td></tr></tbody></table><div class="pagination"><span>共 {{list.length}} 条需求记录</span><div><button>‹</button><button class="active">1</button><button>2</button><button>›</button></div></div></section></MdmShell></template>
